INSERT INTO fbx02_history (fbx02_history_id, fbx02_box_id, fbx02_seq, fbx02_act_cd, fbx02_act_emp_id, fbx02_act_date, fbx02_act_content, fbx02_act_org_code_id)
VALUES (f_create_seq()
      , #{boxId}
      , (SELECT coalesce(max(fbx02_seq), 1) FROM fbx02_history WHERE fbx02_box_id = #{boxId})
      , #{actCode}
      , #{actEmpId}
      , f_sysdate()
      , #{actContent}
      , #{actOrgCodeId})
